templates.home:
{{template "top" .}}<section class="hero"><h1>{{.bizName}}</h1>{{with .tagline}}<p>{{.}}</p>{{end}}<p class="muted">{{.hours}}{{with .address}} · {{.}}{{end}}</p></section>
{{with .error}}<p class="error">{{.}}</p>{{end}}
{{range .groups}}<h2>{{.name}}</h2><div class="list">{{range .services}}<a class="item" href="/s/{{.id}}{{$.qs}}">{{if .image}}<span class="thumb"><img src="{{.image}}?w=160" alt="" loading="lazy"></span>{{end}}
<span class="grow"><strong>{{.name}}</strong><br><span class="muted">{{.duration}} {{$.t.minutes}}{{with .description}} · {{.}}{{end}}</span></span>
<span class="end"><span class="price">AED {{.price}}</span><br><span class="tag">{{$.t.book}}</span></span></a>{{end}}</div>{{end}}
{{if .classes}}<h2>{{.t.classes}}</h2><div class="list">{{range .classes}}<a class="item" href="/c/{{.id}}{{$.qs}}">{{if .image}}<span class="thumb"><img src="{{.image}}?w=160" alt="" loading="lazy"></span>{{end}}
<span class="grow"><strong>{{.name}}</strong>{{with .age}} <span class="tag">{{.}}</span>{{end}}<br><span class="muted">{{$.t.every}} {{.day}} <span dir="ltr">{{.time}}</span> · {{.sessions}} {{$.t.sessions}} · {{.leftText}}</span></span>
<span class="end"><span class="price">AED {{.price}}</span><br><span class="muted">{{$.t.term_price}}</span></span></a>{{end}}</div>{{end}}
{{template "bottom" .}}

templates.service:
{{template "top" .}}{{with .service}}{{if .image}}<div class="photo"><img src="{{.image}}?w=960" alt="{{.name}}"></div>{{end}}
<h1>{{.name}}</h1><p class="muted">{{with .category}}{{.}} · {{end}}{{.duration}} {{$.t.minutes}}</p>{{with .description}}<p>{{.}}</p>{{end}}
<p><span class="price">AED {{.price}}</span> <span class="muted">{{$.t.vat_included}}</span></p>
<form method="post" action="/book" class="panel" id="picker" data-service="{{.id}}">
<input type="hidden" name="service" value="{{.id}}"><input type="hidden" name="lang" value="{{$.lang}}"><input type="hidden" name="time" id="time">
{{with $.error}}<p class="error">{{.}}</p>{{end}}
<label for="staff">{{$.t.staff}}</label><select name="staff" id="staff"><option value="">{{$.t.any_staff}}</option>{{range $.staff}}<option value="{{.id}}">{{.name}}</option>{{end}}</select>
<label for="date">{{$.t.date}}</label><input type="date" name="date" id="date" min="{{$.today}}" max="{{$.maxDate}}" value="{{$.date}}" required>
<label>{{$.t.time}}</label><div class="slots" id="slots" data-none="{{$.t.no_slots}}" data-loading="{{$.t.loading}}"></div>
{{if $.user}}<label for="name">{{$.t.name}}</label><input id="name" name="name" value="{{$.custName}}" required autocomplete="name">
<label for="phone">{{$.t.phone}}</label><input id="phone" name="phone" type="tel" value="{{$.custPhone}}" placeholder="+9715xxxxxxxx" required autocomplete="tel">
{{template "payment" $}}
<p><button id="go" disabled>{{$.t.confirm_booking}}</button></p>
{{else}}<p><a class="btn" href="/_rx/auth/login?next={{$.path}}">{{$.t.sign_in_to_book}}</a></p>{{end}}</form>
<script>
(function(){var p=document.getElementById('picker'),box=document.getElementById('slots'),d=document.getElementById('date'),s=document.getElementById('staff'),t=document.getElementById('time'),go=document.getElementById('go');
function load(){t.value='';if(go)go.disabled=true;box.textContent=box.dataset.loading;
fetch('/api/slots?service='+p.dataset.service+'&staff='+encodeURIComponent(s.value)+'&date='+encodeURIComponent(d.value)).then(function(r){return r.json()}).then(function(j){
box.textContent='';if(!j.slots||!j.slots.length){box.textContent=box.dataset.none;return}
j.slots.forEach(function(x){var b=document.createElement('button');b.type='button';b.className='slot';b.textContent=x.time;
b.onclick=function(){t.value=x.time;[].forEach.call(box.children,function(c){c.classList.remove('on')});b.classList.add('on');if(go)go.disabled=false};box.appendChild(b)})
}).catch(function(){box.textContent=box.dataset.none})}
d.onchange=load;s.onchange=load;load()})();
</script>{{end}}{{template "bottom" .}}

