// POST /enrol  form: class, participant (who attends, e.g. the child), name, phone, payment (card|venue), lang
function handle(req) {
  const f = req.form, lang = f.lang === 'ar' ? 'ar' : 'en', q = lang === 'ar' ? '&lang=ar' : '';
  const back = '/c/' + (Number(f.class) || 0);
  if (!req.user) return {redirect: '/_rx/auth/login?next=' + encodeURIComponent(back + (lang === 'ar' ? '?lang=ar' : ''))};
  const today = dubaiNow().date;
  const c = db.query('SELECT * FROM classes WHERE id = ? AND active = 1', Number(f.class) || 0)[0];
  if (!c || classEnded(c, today)) return {redirect: '/?error=error_gone' + q};
  const name = (f.name || '').trim(), phone = (f.phone || '').trim(), participant = (f.participant || '').trim();
  if (!name || !phone) return {redirect: back + '?error=error_fields' + q};
  if (!participant) return {redirect: back + '?error=error_participant' + q};
  if ((seatsTaken(0)[c.id] || 0) >= c.capacity) return {redirect: back + '?error=error_full' + q};
  const b = business(), pay = terms(b, c.price);
  const method = (f.payment === 'card' && pay.canCard) || !pay.canVenue ? 'card' : 'venue';
  const id = db.exec(`INSERT INTO bookings (user_id, kind, customer_name, phone, email, item, item_ar, service_id, class_id, staff_id, staff_name, staff_name_ar,
    participant, date, time, end_time, price, deposit_due, paid_amount, vat, payment_method, status, lang, reminded)
    VALUES (?, 'class', ?, ?, ?, ?, ?, 0, ?, 0, '', '', ?, ?, ?, ?, ?, ?, 0, ?, ?, ?, ?, 0)`,
    req.user.id, name, phone, req.user.email || '', c.name, c.name_ar || '', c.id, participant,
    classFirstDate(c, today), c.time, hhmm(mins(c.time) + c.duration_min), c.price, method === 'card' ? pay.deposit : 0,
    round2(c.price * 5 / 105), method, method === 'card' ? 'pending' : 'confirmed', lang).lastInsertId;
  // Two visitors taking the last seat at the same moment: the earlier row wins.
  const before = db.query("SELECT COUNT(*) AS n FROM bookings WHERE kind = 'class' AND class_id = ? AND id < ? AND " + HOLDS, c.id, id, holdSince())[0].n;
  if (before >= c.capacity) {
    db.exec('DELETE FROM bookings WHERE id = ?', id);
    return {redirect: back + '?error=error_full' + q};
  }
  return proceed(req, id, lang);
}

