function handle(req) {
  const lang = req.body.lang === 'ar' ? 'ar' : 'en', today = dubaiNow().date, taken = seatsTaken(0);
  const services = db.query('SELECT * FROM services WHERE active = 1 ORDER BY id').map(s => ({id: s.id, name: pick(s, 'name', lang),
    description: pick(s, 'description', lang), category: pick(s, 'category', lang), duration_min: s.duration_min, price: s.price, url: req.origin + '/s/' + s.id}));
  const classes = db.query('SELECT * FROM classes WHERE active = 1 ORDER BY id').filter(c => !classEnded(c, today)).map(c => ({id: c.id, name: pick(c, 'name', lang),
    description: pick(c, 'description', lang), who_for: pick(c, 'age_group', lang), weekday: DAYS[lang][c.weekday], time: c.time, session_minutes: c.duration_min,
    sessions: c.sessions, first_session: classFirstDate(c, today), price_for_term: c.price, seats_left: Math.max(0, c.capacity - (taken[c.id] || 0)), url: req.origin + '/c/' + c.id}));
  return {json: {currency: 'AED', prices_include_vat: true, services: services, classes: classes}};
